CREATE DATABASE IF NOT EXISTS `demo` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `demo`.`student_record` (`id` BIGINT NOT NULL AUTO_INCREMENT, `student_no` VARCHAR(32) NOT NULL, `name` VARCHAR(64) NOT NULL, `age` INT NULL, `gender` VARCHAR(16) NULL, `class_name` VARCHAR(64) NULL, `email` VARCHAR(128) NULL, `birthday` VARCHAR(32) NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_student_record_student_no` (`student_no`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `demo`.`file_record` (`id` BIGINT NOT NULL AUTO_INCREMENT, `file_id` VARCHAR(64) NOT NULL, `original_name` VARCHAR(255) NOT NULL, `object_key` VARCHAR(512) NOT NULL, `bucket_name` VARCHAR(128) NOT NULL, `content_type` VARCHAR(128) NULL, `file_size` BIGINT NOT NULL, `file_md5` CHAR(32) NOT NULL, `file_ext` VARCHAR(32) NULL, `storage_type` VARCHAR(32) NOT NULL, `status` VARCHAR(32) NOT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_file_record_file_id` (`file_id`), KEY `idx_file_record_md5_size` (`file_md5`, `file_size`), KEY `idx_file_record_status_created_at` (`status`, `created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `demo`.`file_upload_task` (`id` BIGINT NOT NULL AUTO_INCREMENT, `upload_id` VARCHAR(64) NOT NULL, `file_id` VARCHAR(64) NOT NULL, `upload_type` VARCHAR(32) NOT NULL, `original_name` VARCHAR(255) NOT NULL, `object_key` VARCHAR(512) NOT NULL, `part_object_prefix` VARCHAR(512) NULL, `bucket_name` VARCHAR(128) NOT NULL, `content_type` VARCHAR(128) NULL, `file_size` BIGINT NOT NULL, `file_md5` CHAR(32) NOT NULL, `file_ext` VARCHAR(32) NULL, `status` VARCHAR(32) NOT NULL, `part_size` BIGINT NULL, `part_count` INT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `completed_at` DATETIME NULL, PRIMARY KEY (`id`), UNIQUE KEY `uk_file_upload_task_upload_id` (`upload_id`), KEY `idx_file_upload_task_status_created_at` (`status`, `created_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
